evidence.en:
function process(items) {
  if (items.length === 0) return;
  handle(items[0]);
  // re-scans ALL remaining items on every call:
  const rest = items.filter((x) => x.id !== items[0].id);
  process(rest);
}
// staging: 200 items — instant
// prod: 100,000 items — hours

